{% comment %} Alle Testimonials ausgeben {% endcomment %}
{% assign testimonials = shop.metaobjects.testimonial.values %}
{% for entry in testimonials %}
  <blockquote>
    <p>{{ entry.fields.quote.value }}</p>
    <footer>
      <strong>{{ entry.fields.author_name.value }}</strong>
      {% if entry.fields.company.value %}
        – {{ entry.fields.company.value }}
      {% endif %}
    </footer>
  </blockquote>
{% endfor %}

{% comment %} Referenz von einem Produkt-Metafield auf ein Metaobject {% endcomment %}
{% assign guide = product.metafields.custom.size_guide.value %}
{% if guide %}
  <div class="size-guide">
    <h3>{{ guide.fields.title.value }}</h3>
    {{ guide.fields.description.value }}
  </div>
{% endif %}

content_en.text:
{% assign team = shop.metaobjects.team_member.values %}
{% for member in team %}
  <div class="team-card">
    <img src="{{ member.photo | image_url: width: 400 }}" alt="{{ member.name }}">
    <h3>{{ member.name }}</h3>
    <p>{{ member.role }}</p>
  </div>
{% endfor %}
